from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
catalog=json.loads((R/'source/catalog.json').read_text())
def read(p): return (R/p).read_text()
games=''.join(f'''<article class="game" style="--accent:{color}"><span class="number">0{i+1}</span><img src="artwork/{name}-512.webp" alt="{name.replace('-',' ')} dimensional emblem"><div class="game-footer"><h3>{name.replace('-',' ')}</h3><span class="glyph">{read(f'games/{name}-glyph.svg')}</span></div></article>''' for i,(name,color) in enumerate(catalog['games'].items()))
icons=''.join(f'<div class="icon-cell" data-name="{name}">{read(f"ui/{name}.svg")}<span>{name}</span></div>' for name in catalog['ui'])
badges=''.join(f'<img src="games/{name}-badge.svg" alt="{name} vector badge">' for name in catalog['games'])
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AM Arcade · Iconography</title><link rel="icon" href="favicon/favicon.svg"><style>
*{box-sizing:border-box}body{margin:0;background:#090617;color:#f4efff;font-family:Arial,Helvetica,sans-serif}main{max-width:1320px;margin:auto;padding:38px 56px 56px}header{display:flex;align-items:center;justify-content:space-between;padding-bottom:27px;border-bottom:1px solid #ffffff20}.brand{width:175px}.eyebrow{font:11px monospace;letter-spacing:2px;text-transform:uppercase;color:#b4a8cc}.status{display:flex;align-items:center;gap:10px}.dot{width:6px;height:6px;background:#00e5ff;box-shadow:0 0 12px #00e5ff;border-radius:50%}.hero{display:grid;grid-template-columns:1.25fr 1fr;align-items:center;min-height:430px;position:relative}.hero:after{content:'';position:absolute;right:0;top:0;width:45%;height:100%;background:radial-gradient(ellipse,#6c1fc42a,transparent 65%);pointer-events:none}.hero h1{font-size:68px;line-height:.98;letter-spacing:-3.5px;margin:23px 0}.hero h1 span{color:#00e5ff}.hero p{color:#b4a8cc;font-size:15px;line-height:1.7;max-width:395px}.hero-art{width:340px;height:380px;object-fit:contain;justify-self:center;z-index:1}.pills{display:flex;gap:9px;margin-top:23px}.pills span{border:1px solid #49345f;padding:7px 10px;font:10px monospace;color:#dac8ec}.section-heading{display:flex;align-items:baseline;justify-content:space-between;margin:15px 0 22px}.section-heading h2{font-size:20px;letter-spacing:-.5px;margin:0}.section-heading p{font:10px monospace;letter-spacing:1px;color:#b4a8cc}.games{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.game{background:linear-gradient(155deg,#1f1431,#100b1b);border:1px solid #372444;border-top:2px solid var(--accent);border-radius:12px;padding:15px 12px 14px;position:relative;overflow:hidden}.game .number{font:10px monospace;color:var(--accent)}.game>img{width:100%;height:158px;object-fit:contain;margin:2px 0 15px}.game-footer{display:flex;align-items:center;justify-content:space-between;gap:5px}.game h3{font-size:11px;text-transform:uppercase;letter-spacing:.6px;margin:0}.glyph{color:var(--accent);width:22px;height:22px;flex:none}.system{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:28px 0 34px}.panel{border:1px solid #372444;padding:22px;border-radius:12px;background:#100b1b}.panel-title{font:10px monospace;letter-spacing:1px;color:#b4a8cc;text-transform:uppercase}.size-row{display:flex;flex-wrap:wrap;gap:22px;align-items:center;margin:19px 0}.size{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:10px;font:10px monospace;color:#b4a8cc}.size>div{height:64px;display:flex;align-items:center}.badges{display:flex;justify-content:space-between;gap:14px;margin-top:26px}.badges img{width:66px;height:66px}.ui-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.tools{display:flex;gap:8px}input,button{border:1px solid #49345f;border-radius:6px;background:#161027;color:#f4efff;padding:9px 12px;font:12px Arial}input{width:190px}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:2px solid #00e5ff;outline-offset:3px}.icons{display:grid;grid-template-columns:repeat(10,1fr);border-top:1px solid #372444;border-left:1px solid #372444;border-radius:10px;overflow:hidden;margin-top:18px}.icon-cell{display:flex;flex-direction:column;align-items:center;gap:15px;padding:22px 4px 16px;border-bottom:1px solid #372444;border-right:1px solid #372444;color:#ddc9f3;min-width:0}.icon-cell svg{width:26px;height:26px;color:#00e5ff}.icon-cell span{font:9px monospace}.icon-cell[hidden]{display:none}.icons.light{background:#f4efff}.icons.light .icon-cell{color:#251338}.icons.light svg{color:#251338}.empty{color:#b4a8cc;font-size:13px}.swatches{display:flex;gap:14px;margin-top:28px}.swatch{display:flex;align-items:center;gap:8px;font:10px monospace;color:#b4a8cc}.swatch i{width:12px;height:12px;border-radius:3px;background:var(--c);border:1px solid #ffffff25}footer{margin-top:26px;padding-top:24px;border-top:1px solid #ffffff20;display:flex;justify-content:space-between;color:#b4a8cc;font:10px monospace;line-height:1.8}footer a{color:#00e5ff} @media(max-width:900px){main{padding:24px}.hero h1{font-size:52px}.hero-art{width:100%;height:300px}.games{grid-template-columns:repeat(3,1fr)}.icons{grid-template-columns:repeat(5,1fr)}.system{grid-template-columns:1fr}.eyebrow{font-size:9px}.swatches{flex-wrap:wrap}}@media(max-width:560px){.hero{grid-template-columns:1fr}.hero-art{height:260px}.hero h1{font-size:48px}.games{grid-template-columns:repeat(2,1fr)}.icons{grid-template-columns:repeat(4,1fr)}.ui-head{align-items:start;flex-direction:column}.status{display:none}.badges{gap:6px}.badges img{width:50px}.section-heading p{display:none}footer{gap:16px}.swatch{font-size:9px}}
</style></head><body><main><header><img class="brand" src="brand/wordmark-dark.svg" alt="AM Arcade"><div class="status eyebrow"><i class="dot"></i> Iconography collection / 01</div></header><section class="hero"><div><div class="eyebrow">Blacklight metal · Electric color</div><h1>Small marks.<br><span>Arcade energy.</span></h1><p>A luminous cabinet identity, five collectible game emblems, and a complete family of precision interface icons.</p><div class="pills"><span>06 DIMENSIONAL ASSETS</span><span>40 UI ICONS</span><span>SVG + PNG + WEBP</span></div></div><img class="hero-art" src="artwork/am-arcade-512.webp" alt="Violet arcade cabinet with cyan A emblem"></section><div class="section-heading"><h2>The machine collection</h2><p>INDIVIDUAL TRANSPARENT ARTWORK</p></div><section class="games">GAMES</section><section class="system"><div class="panel"><div class="panel-title">The signature / from tab to app</div><div class="size-row"><div class="size"><div><img src="favicon/favicon-16.png" width="16" height="16" alt="16 pixel favicon"></div>16 px</div><div class="size"><div><img src="favicon/favicon-32.png" width="32" height="32" alt="32 pixel favicon"></div>32 px</div><div class="size"><div><img src="favicon/favicon-48.png" width="48" height="48" alt="48 pixel favicon"></div>48 px</div><div class="size"><div><img src="brand/app-icon.svg" width="64" height="64" alt="64 pixel app icon"></div>64 px</div><img src="brand/wordmark-dark.svg" style="width:170px;max-width:35%;margin-left:auto" alt="AM Arcade wordmark"></div></div><div class="panel"><div class="panel-title">Companion vectors / cabinet badges</div><div class="badges">BADGES</div></div></section><section><div class="ui-head"><div><h2 style="font-size:20px;margin:0 0 6px">The interface family</h2><span class="eyebrow">24-unit grid / currentColor / 1.8-unit stroke</span></div><div class="tools"><input id="search" type="search" placeholder="Find an icon…" aria-label="Filter icons"><button id="theme" aria-pressed="false">Light surface</button></div></div><div class="icons" id="icons">ICONS</div><p id="empty" class="empty" hidden>No matching icons.</p></section><div class="swatches"><div class="swatch" style="--c:#090617"><i></i>MIDNIGHT #090617</div><div class="swatch" style="--c:#00e5ff"><i></i>CYAN #00E5FF</div><div class="swatch" style="--c:#ff2bd6"><i></i>PINK #FF2BD6</div><div class="swatch" style="--c:#ffe066"><i></i>IVORY #FFE066</div></div><footer><span>AM ARCADE<br>ICONOGRAPHY / V1</span><span>Ready for integration<br><a href="README.md">Asset guide &amp; usage notes ↗</a></span></footer></main><script>const search=document.querySelector('#search'),cells=[...document.querySelectorAll('.icon-cell')];search.addEventListener('input',()=>{let count=0;for(const c of cells){c.hidden=!c.dataset.name.includes(search.value.toLowerCase().trim());if(!c.hidden)count++}document.querySelector('#empty').hidden=count>0});document.querySelector('#theme').addEventListener('click',e=>{const light=document.querySelector('#icons').classList.toggle('light');e.target.textContent=light?'Dark surface':'Light surface';e.target.setAttribute('aria-pressed',String(light))});</script></body></html>'''
(R/'index.html').write_text(html.replace('GAMES',games).replace('BADGES',badges).replace('ICONS</div>',icons+'</div>'))
